package io.github.chronicle.core.areas;

import java.io.*;import java.nio.file.Path;import java.util.*;
/** Strict bounded atomic operation journal; incomplete and historical evidence is retained. */
public final class AreaOperationStore implements AreaOperationRepository{
    private static final int MAGIC=0x43484f50,SCHEMA=1;public static final long MAX_BYTES=64L*1024*1024;private final AtomicAreaFile file;private boolean loadedValid;
    public AreaOperationStore(Path file){this.file=new AtomicAreaFile(file,MAX_BYTES);}
    @Override public synchronized AreaOperationJournal load()throws IOException{byte[] b=file.load();if(b==null){loadedValid=true;return AreaOperationJournal.empty();}try{AreaOperationJournal result=decode(b);loadedValid=true;return result;}catch(RuntimeException e){loadedValid=false;throw new IOException("area operation journal is invalid and was preserved",e);}}
    @Override public synchronized void save(AreaOperationJournal journal)throws IOException{if(!loadedValid)throw new IOException("load a valid operation journal before saving");file.save(encode(journal));}
    static byte[] encode(AreaOperationJournal journal)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeInt(SCHEMA);out.writeLong(journal.revision());out.writeInt(journal.operations().size());for(AreaOperation o:journal.operations().values()){AreaBinary.text(out,o.operationId().toString());AreaBinary.text(out,o.intent().name());AreaBinary.text(out,o.areaId());AreaBinary.text(out,o.areaName());out.writeLong(o.areaRevision());AreaBinary.bounds(out,o.bounds());out.writeBoolean(o.requestedState().isPresent());if(o.requestedState().isPresent())AreaBinary.text(out,o.requestedState().get().name());AreaBinary.optionalRef(out,o.before());AreaBinary.optionalRef(out,o.after());AreaBinary.text(out,o.actor().toString());out.writeInt(o.cursor());AreaBinary.text(out,o.stage().name());out.writeBoolean(o.deletionObligation());AreaBinary.text(out,o.detail());AreaBinary.text(out,o.createdAt());}}return bytes.toByteArray();}
    static AreaOperationJournal decode(byte[] bytes){try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){if(in.readInt()!=MAGIC||in.readInt()!=SCHEMA)throw new IllegalArgumentException("operation journal magic/schema is invalid");long revision=in.readLong();int n=AreaBinary.count(in,AreaOperationJournal.MAX_OPERATIONS,"operation");Map<UUID,AreaOperation> map=new LinkedHashMap<>();for(int i=0;i<n;i++){UUID id=uuid(AreaBinary.text(in,36,"operation ID"));AreaOperation.Intent intent=enumValue(AreaOperation.Intent.class,AreaBinary.text(in,32,"intent"));String areaId=AreaBinary.text(in,129,"area ID");String name=AreaBinary.text(in,AreaChange.MAX_NAME_BYTES,"area name");long areaRevision=in.readLong();AreaBounds bounds=AreaBinary.bounds(in);Optional<AreaState> requested=in.readBoolean()?Optional.of(enumValue(AreaState.class,AreaBinary.text(in,16,"requested state"))):Optional.empty();Optional<SnapshotRef> before=AreaBinary.optionalRef(in),after=AreaBinary.optionalRef(in);UUID actor=uuid(AreaBinary.text(in,36,"actor"));int cursor=in.readInt();AreaOperation.Stage stage=enumValue(AreaOperation.Stage.class,AreaBinary.text(in,32,"stage"));boolean deleting=in.readBoolean();String detail=AreaBinary.textAllowEmpty(in,4096,"detail");String created=AreaBinary.text(in,128,"created time");AreaOperation o=new AreaOperation(id,intent,areaId,name,areaRevision,bounds,requested,before,after,actor,cursor,stage,deleting,detail,created);if(map.putIfAbsent(id,o)!=null)throw new IllegalArgumentException("duplicate operation ID");}if(in.read()!=-1)throw new IllegalArgumentException("operation journal has trailing bytes");return new AreaOperationJournal(revision,map);}catch(EOFException e){throw new IllegalArgumentException("operation journal is truncated",e);}catch(IOException e){throw new IllegalArgumentException("operation journal cannot be decoded",e);}}
    private static UUID uuid(String value){try{UUID id=UUID.fromString(value);if(!id.toString().equals(value))throw new IllegalArgumentException();return id;}catch(RuntimeException e){throw new IllegalArgumentException("UUID is not canonical",e);}}
    private static <T extends Enum<T>>T enumValue(Class<T>type,String value){try{return Enum.valueOf(type,value);}catch(RuntimeException e){throw new IllegalArgumentException("unknown "+type.getSimpleName(),e);}}
}
